# Let me properly extract and analyze the two structures from the demo
import json

with open('/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/held-out-4/play/users/u073/system/state/workspace/programs/task-1c22fb85.json') as f:
    demos = json.load(f)

input_grid = demos[0]['input']
output_grid = demos[0]['output']

rows, cols = len(input_grid), len(input_grid[0])
print(f"Grid size: {rows}x{cols}")

def find_structures(grid):
    structures = []
    visited = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r,c) not in visited:
                struct_cells = []
                queue = [(r, c)]
                visited.add((r, c))
                while queue:
                    cr, cc = queue.pop(0)
                    struct_cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] != 0 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                colors_pos = {}
                for cr, cc in struct_cells:
                    col = grid[cr][cc]
                    colors_pos[col] = colors_pos.get(col, 0) + 1
                min_r, max_r = min(cr for cr, cc in struct_cells), max(cr for cr, cc in struct_cells)
                min_c, max_c = min(cc for cr, cc in struct_cells), max(cc for cr, cc in struct_cells)
                structures.append({
                    'cells': sorted(struct_cells),
                    'min_r': min_r, 'max_r': max_r,
                    'min_c': min_c, 'max_c': max_c,
                    'colors': colors_pos,
                    'input_subgrid': [row[min_c:max_c+1] for row in grid[min_r:max_r+1]],
                    'output_subgrid': [row[min_c:max_c+1] for row in output_grid[min_r:max_r+1]]
                })
    return structures

structures = find_structures(input_grid)
print(f"Found {len(structures)} structures\n")

for i, s in enumerate(structures):
    print(f"=== Structure {i+1} ===")
    print(f"Location: rows {s['min_r']} - {s['max_r']}, cols {s['min_c']} - {s['max_c']}")
    print("Input colors:", s['colors'])
    out_colors = {}
    for row in s['output_subgrid']:
        for c in row:
            out_colors[c] = out_colors.get(c, 0) + 1
    print("Output colors:", out_colors)
    print("Input subgrid:")
    for row in s['input_subgrid']:
        print(" ", "".join(str(c) for c in row))
    print("Output subgrid:")
    for row in s['output_subgrid']:
        print(" ", "".join(str(c) for c in row))

